{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 등록칩으로 확인된 보호소 내 강아지를 공고 종료 전에 데려올 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "등록칩으로 확인된 보호소 내 강아지는 공고 종료 전이라도 소유자가 반환을 요청하면 즉시 데려올 수 있습니다. 서울특별시 동물보호 조례 제10조 제4항은 보호조치 중인 자가 공고기간 중 소유자가 반환을 요청하는 경우 즉시 반환하도록 정하고 있습니다. 또한 제16조 제1항은 등록된 동물일 경우 구청장이 소유자에게 즉시 반환하도록 하고, 제16조 제2항은 소유자가 반환 요구기간 내에 반환을 요구하면 정보를 확인하여 확실한 경우 지체 없이 반환하도록 정하고 있습니다.",
          "b_ids": "동물보호:제10조제4항, 동물보호:제16조제1항, 동물보호:제16조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
